    #[local] Abbreviation agree_block_via_eff := (@HEmplaceU1A.agree_block_via_eff AC L MI HLrw_img HLerr_rw).
    #[local] Abbreviation SS := (@HEmplaceU1A.SS NEW_STACK DEL_STACK).
    #[local] Abbreviation W := (@HEmplaceU1A.W NEW_STACK DEL_STACK sp).
    #[local] Abbreviation base_ok := (@HEmplaceU1A.base_ok L R0 sp).
