    #[local] Abbreviation sp_facts := (@HEmplaceU1A.sp_facts AC L MI ST NEW_STACK DEL_STACK NEW_STACK_nn A0 s R0 M0 model0 sp ret keyp2 CB).
    #[local] Abbreviation bc_facts := (@HEmplaceU1A.bc_facts AC L MI ST NEW_STACK DEL_STACK fx A0 s R0 M0 model0 sp ret obj bl bc keyp2 key ents K U0 Hlast ROOM2 CONT).
    #[local] Abbreviation foot_low_or_high := (@HEmplaceU1A.foot_low_or_high AC L MI ST NEW_STACK DEL_STACK NEW_STACK_nn DEL_STACK_nn A0 s R0 M0 model0 sp ret obj bl bc keyp2 ents CB U0 ASP).
    #[local] Abbreviation foot_low_or_high_gen := (@HEmplaceU1A.foot_low_or_high_gen AC L MI ST NEW_STACK DEL_STACK NEW_STACK_nn DEL_STACK_nn A0 s R0 M0 model0 sp ret obj keyp2 CB ASP).
    #[local] Abbreviation foot_offimg_gen := (@HEmplaceU1A.foot_offimg_gen AC L MI ST NEW_STACK DEL_STACK NEW_STACK_nn DEL_STACK_nn HLimg_lo A0 s R0 M0 model0 sp ret obj keyp2 CB ASP).
    #[local] Abbreviation foot_apart_new := (@HEmplaceU1A.foot_apart_new AC L MI ST NEW_STACK DEL_STACK NEW_STACK_nn DEL_STACK_nn fx A0 s R0 M0 model0 sp ret obj bl bc keyp2 key ents K CB U0 ASP CONT).
    #[local] Abbreviation pst := (@HEmplaceU1A.pst L NEW_STACK DEL_STACK R0 M0 sp ret obj bc tupp key).
    #[local] Abbreviation phaseA := (@HEmplaceU1A.phaseA AC L MI ST NEW_STACK DEL_STACK NEW_STACK_nn DEL_STACK_nn fx A0 s R0 M0 model0 sp ret obj bl bc keyp tupp keyp2 key ents K CB H10 H11 H13 U0 ASP ASK CK Hlast ROOM2 CONT).
    #[local] Abbreviation epilogue := (@HEmplaceU1A.epilogue AC L MI ST NEW_STACK DEL_STACK NEW_STACK_nn DEL_STACK_nn HLimg_lo HLrw_img HLrelro_img HLrw_relro HLerr_rw fx A0 s R0 M0 model0 sp ret obj bl bc keyp2 key ents K CB CONT).
    #[local] Abbreviation phaseFound := (@HEmplaceU1A.phaseFound AC L MI ST NEW_STACK DEL_STACK NEW_STACK_nn DEL_STACK_nn HLimg_lo HLrw_img HLrelro_img HLrw_relro HLerr_rw fx A0 s R0 M0 model0 sp ret obj bl bc tupp keyp2 key ents K CB FRM U0 ASP CONT).
    #[local] Abbreviation nst := (@HEmplaceU1A.nst AC L MI NEW_STACK DEL_STACK A0 R0 M0 model0 sp ret obj bl bc tupp keyp2 key ents).
    #[local] Abbreviation phaseN := (@HEmplaceU1A.phaseN AC L MI ST NEW_STACK DEL_STACK NEW_STACK_nn DEL_STACK_nn NEW HLnew HLimg_lo HLrw_img HLrelro_img HLrw_relro HLerr_rw fx A0 s R0 M0 model0 sp ret obj bl bc tupp keyp2 key ents K CB U0 ASP AST ASK2 CT CK2 ROC HNMAX ROOM1 CONT).
    #[local] Abbreviation core := (@HEmplaceU1A.core AC L MI NEW_STACK DEL_STACK A0 R0 model0 sp ret obj key).
