    Ltac x_lui MS Fx Dx znext :=
      eapply srz_msteps; [eapply ms_halt; exact MS | eapply ms_lazy; exact MS | | ];
      [ norm_pc; eapply msteps_one; [reflexivity | exact (step_lui _ _ _ _ _ _ _ _ Fx eq_refl Dx)]
      | cbv beta iota; lazymatch goal with |- context [bv_eqb ?r 0%bv] => replace (bv_eqb r 0%bv) with false by reflexivity | _ => idtac end;
        cbv beta iota; unfold v_lui; zpc znext ].

    Ltac fp_fmv MS Fx Dx Qrs v znext :=
      let Hst := fresh "Hst" in
      lazymatch goal with |- srealizes _ (mkCfg (@mkst ?fx1 ?R _ ?M ?rom) _) _ =>
        pose proof (hp_step_fmv_w_x fx1 SEGS R _ M rom _ _ _ _ Fx eq_refl Dx Qrs) as Hst;
        lazymatch type of Hst with context [Z_to_bv 32 (?c mod 2 ^ 32)] => replace (c mod 2 ^ 32) with v in Hst by reflexivity end;
        eapply srz_msteps; [eapply ms_halt; exact MS | eapply ms_lazy; exact MS | | ];
        [ norm_pc; eapply msteps_one; [reflexivity | exact Hst] | clear Hst; zpc znext ]
      end.

    Ltac fp_fsgnj MS Fx Dx Ha Hb znext :=
      let Hst := fresh "Hst" in
      lazymatch goal with |- srealizes _ (mkCfg (@mkst ?fx1 ?R _ ?M ?rom) _) _ =>
        pose proof (hp_step_fsgnj_s fx1 SEGS R _ M rom _ _ _ _ _ _ _ Fx eq_refl Dx Ha Hb ltac:(unfold two23f, neg1f, two64f in *; lia) ltac:(unfold two23f, neg1f, two64f in *; lia) ltac:(discriminate)) as Hst;
        eapply srz_msteps; [eapply ms_halt; exact MS | eapply ms_lazy; exact MS | | ];
        [ norm_pc; eapply msteps_one; [reflexivity | exact Hst] | clear Hst; zpc znext ]
      end.

    Ltac fp_fltc MS Fx Dx Ha Hb VAL znext :=
      let Hst := fresh "Hst" in
      lazymatch goal with |- srealizes _ (mkCfg (@mkst ?fx1 ?R _ ?M ?rom) _) _ =>
        pose proof (hp_step_fcmp_s fx1 SEGS R _ M rom _ _ _ _ _ _ _ Fx eq_refl Dx Ha Hb ltac:(unfold two23f, neg1f, two64f in *; lia) ltac:(unfold two23f, neg1f, two64f in *; lia)) as Hst;
        cbv zeta in Hst; cbn [fcmp_op] in Hst; rewrite VAL in Hst; cbn [fst snd] in Hst; rewrite accrue_no_flags in Hst;
        lazymatch type of Hst with context [bv_eqb ?r 0%bv] => replace (bv_eqb r 0%bv) with false in Hst by reflexivity end; cbv beta iota in Hst;
        eapply srz_msteps; [eapply ms_halt; exact MS | eapply ms_lazy; exact MS | | ];
        [ norm_pc; eapply msteps_one; [reflexivity | exact Hst] | clear Hst; zpc znext ]
      end.

    Ltac fp_fcvt_w_s MS Fx Dx FZ Ha n znext :=
      let md := fresh "md" in let Hmd := fresh "Hmd" in let Hst := fresh "Hst" in
      lazymatch goal with |- srealizes _ (mkCfg (@mkst ?fx1 ?R _ ?M ?rom) _) _ =>
        destruct (hp_step_fcvt_w_s fx1 SEGS R _ M rom _ true _ _ _ _ Fx eq_refl Dx FZ ltac:(left; vm_compute; discriminate) Ha ltac:(lia)) as (md & Hmd & Hst);
        cbv zeta in Hst; rewrite (to_w_val md n) in Hst by lia; cbn [fst snd] in Hst; rewrite accrue_no_flags, sext64_w_small in Hst by lia;
        lazymatch type of Hst with context [bv_eqb ?r 0%bv] => replace (bv_eqb r 0%bv) with false in Hst by reflexivity end; cbv beta iota in Hst;
        eapply srz_msteps; [eapply ms_halt; exact MS | eapply ms_lazy; exact MS | | ];
        [ norm_pc; eapply msteps_one; [reflexivity | exact Hst] | clear Hst Hmd md; zpc znext ]
      end.

    Ltac fp_fcvt_s_w MS Fx Dx FZ Qrs n znext :=
      let md := fresh "md" in let Hmd := fresh "Hmd" in let Hst := fresh "Hst" in
      lazymatch goal with |- srealizes _ (mkCfg (@mkst ?fx1 ?R _ ?M ?rom) _) _ =>
        destruct (hp_step_fcvt_s_w fx1 SEGS R _ M rom _ true _ _ _ Fx eq_refl Dx FZ ltac:(left; vm_compute; discriminate)) as (md & Hmd & Hst);
        cbv zeta in Hst; rewrite Qrs, (u64_of_Z n), (of_int_val_gen md true 32 n) in Hst by lia; cbn [fst snd] in Hst; rewrite accrue_no_flags in Hst;
        eapply srz_msteps; [eapply ms_halt; exact MS | eapply ms_lazy; exact MS | | ];
        [ norm_pc; eapply msteps_one; [reflexivity | exact Hst] | clear Hst Hmd md; zpc znext ]
      end.

    Definition gregs (p : Z) (R : bvmap 5 word) : Prop :=
      base_ok R /\ getr R 8%bv = Z_to_bv 64 obj /\ getr R 10%bv = Z_to_bv 64 p /\ getr R 18%bv = Z_to_bv 64 bc /\ getr R 19%bv = Z_to_bv 64 key.

    Lemma gregs_upd : forall p R r v, gregs p R -> ~ In r [2; 3; 4; 8; 10; 18; 19; 21; 22; 23; 24; 25; 26; 27]%bv -> gregs p (regupd R r v).
