    Ltac gregs_from HR' G :=
      let B := fresh in let Q8 := fresh in let Q10 := fresh in let Q18 := fresh in let Q19 := fresh in
      destruct G as (B & Q8 & Q10 & Q18 & Q19); unfold gregs;
      split; [base_from HR' B|];
      split; [let Q := fresh in rreg HR' 8%bv Q; exact Q|];
      split; [let Q := fresh in rreg HR' 10%bv Q; exact Q|];
      split; [let Q := fresh in rreg HR' 18%bv Q; exact Q| let Q := fresh in rreg HR' 19%bv Q; exact Q].

    Lemma phaseR1a : forall (fx1 : FPState) p M model R,
      mstd model -> gregs p R ->
      (forall R' (pcd : Z), (pcd = FDIV_A /\ 3 <= bc \/ pcd = FDIV_B /\ bc < 3) -> gregs p R' -> getr R' 11%bv = Z_to_bv 64 1 ->
          srealizes SEGS (cfg fx1 R' pcd M model) K) ->
      srealizes SEGS (cfg fx1 R GROW M model) K.
