      mstd model -> gregs p R -> getr R 11%bv = Z_to_bv 64 1 ->
      frm_zero (@fp_csr fx1) -> fkept_u1 fx fx1 -> fholds fx1 15%bv (ieee (Zlength ents + 1)) -> (bc = 0 \/ Zlength ents = bc) ->
      (forall (fx2 : FPState) R', frm_zero (@fp_csr fx2) -> fkept_u1 fx fx2 -> base_ok R' ->
          getr R' 8%bv = Z_to_bv 64 obj -> getr R' 9%bv = Z_to_bv 64 p -> getr R' 19%bv = Z_to_bv 64 key ->
          getr R' 10%bv = Z_to_bv 64 obj -> getr R' 11%bv = Z_to_bv 64 (rw_arg bc) -> getr R' 1%bv = Z_to_bv 64 RWR ->
          srealizes SEGS (cfg fx2 R' RW M model) K) ->
      srealizes SEGS (cfg fx1 R CHK M model) K.
